// Validate payload shape and drop obviously noisy/duplicate readings.
const p = msg.payload;
if (!p || !p.store_id || !p.sku_id || typeof p.quantity !== 'number') {
    node.warn('Dropped malformed shelf reading');
    return null;
}

// Simple noise filter: ignore negative or implausibly large jumps
// (a real implementation would compare against the last known value
// held in flow/context storage - stubbed here for Week 3).
if (p.quantity < 0 || p.quantity > 100000) {
    node.warn(`Dropped implausible reading for ${p.store_id}#${p.sku_id}`);
    return null;
}

msg.payload = {
    store_id: p.store_id,
    sku_id: p.sku_id,
    quantity: p.quantity,
    source: 'shelf_sensor',
    normalised_at: new Date().toISOString()
};
// partition_key lets downstream nodes / the event bus route by store
// without inspecting the full payload, matching the store_id#sku_id
// partitioning strategy used for DynamoDB.
msg.partition_key = `${p.store_id}#${p.sku_id}`;
return msg;

const p = msg.payload;
if (!p || !p.store_id || !p.sku_id || typeof p.quantity_sold !== 'number') {
    node.warn('Dropped malformed POS event');
    return null;
}

msg.payload = {
    store_id: p.store_id,
    sku_id: p.sku_id,
    quantity_sold: p.quantity_sold,
    unit_price: p.unit_price,
    promo_active: !!p.promo_active,
    source: 'pos',
    normalised_at: new Date().toISOString()
};
msg.partition_key = `${p.store_id}#${p.sku_id}`;
return msg;

// Placeholder threshold - Week 4+ will read the real reorder
// threshold from DynamoDB (StockLevels table) instead of a constant.
const LOW_STOCK_THRESHOLD = 15;

msg.low_stock = msg.payload.quantity < LOW_STOCK_THRESHOLD;
return msg;
